package com.ketsh11.dorgeshkaanchests;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Keybind;
import net.runelite.client.config.Range;

@ConfigGroup("dorgeshkaanchests")
public interface DorgeshKaanChestConfig extends Config
{
	@ConfigItem(
		keyName = "lootableColor",
		name = "Lootable color",
		description = "Color for chests that can be pick-locked"
	)
	default Color lootableColor()
	{
		return Color.GREEN;
	}

	@ConfigItem(
		keyName = "lootedColor",
		name = "Looted color",
		description = "Color for chests that are currently looted / unavailable"
	)
	default Color lootedColor()
	{
		return Color.RED;
	}

	@ConfigItem(
		keyName = "openingColor",
		name = "Opening color",
		description = "Color for chests that are in the opening animation/state"
	)
	default Color openingColor()
	{
		return Color.YELLOW;
	}

	@Range(
		min = 1,
		max = 8
	)
	@ConfigItem(
		keyName = "outlineWidth",
		name = "Outline width",
		description = "Overlay outline width"
	)
	default int outlineWidth()
	{
		return 2;
	}

	@Range(
		min = 0,
		max = 255
	)
	@ConfigItem(
		keyName = "fillOpacity",
		name = "Fill opacity",
		description = "Opacity of chest fill color (0-255)"
	)
	default int fillOpacity()
	{
		return 65;
	}

	@ConfigItem(
		keyName = "hopHotkey",
		name = "Hop hotkey",
		description = "Press to hop when HOP NOW is active"
	)
	default Keybind hopHotkey()
	{
		return Keybind.NOT_SET;
	}

	@ConfigItem(
		keyName = "hopFilterSource",
		name = "Hop filter source",
		description = "Choose internal filtering or World Hopper plugin filters"
	)
	default HopFilterSource hopFilterSource()
	{
		return HopFilterSource.INTERNAL;
	}

	@Range(
		min = 4000,
		max = 8000
	)
	@ConfigItem(
		keyName = "hopCountdownMillis",
		name = "Hop timer (ms)",
		description = "Countdown duration after 'You attempt to pick the lock.'"
	)
	default int hopCountdownMillis()
	{
		return 5500;
	}

	@ConfigItem(
		keyName = "showStatistics",
		name = "Show statistics",
		description = "Display session stats under the center banner"
	)
	default boolean showStatistics()
	{
		return false;
	}

	@Range(
		min = 0,
		max = 700
	)
	@ConfigItem(
		keyName = "defaultWorld",
		name = "Default world",
		description = "Cycle restart world for hotkey hopping (0 = disabled)"
	)
	default int defaultWorld()
	{
		return 0;
	}

	@Range(
		min = 1,
		max = 50
	)
	@ConfigItem(
		keyName = "hopCycleLength",
		name = "Hop cycle length",
		description = "After this many hotkey hops, restart at default world"
	)
	default int hopCycleLength()
	{
		return 15;
	}

	@Range(
		min = 60,
		max = 900
	)
	@ConfigItem(
		keyName = "chestRespawnSeconds",
		name = "Chest respawn (s)",
		description = "Time before returning to default world is considered worthwhile"
	)
	default int chestRespawnSeconds()
	{
		return 300;
	}

	@ConfigItem(
		keyName = "afkSafeMode",
		name = "AFK-safe mode",
		description = "Only show strong alerts for HOP NOW / ALL CHESTS LOOTED, with flash + beep"
	)
	default boolean afkSafeMode()
	{
		return false;
	}

}

package com.ketsh11.dorgeshkaanchests;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Shape;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

public class DorgeshKaanChestOverlay extends Overlay
{
	private final DorgeshKaanChestPlugin plugin;

	@Inject
	private DorgeshKaanChestOverlay(DorgeshKaanChestPlugin plugin)
	{
		this.plugin = plugin;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		DorgeshKaanChestConfig config = plugin.getConfig();
		graphics.setStroke(new BasicStroke(config.outlineWidth()));

		for (DorgeshKaanChestPlugin.ChestState chestState : plugin.getChestStates())
		{
			Color baseColor;
			switch (chestState.getRenderState())
			{
				case LOOTED:
					baseColor = config.lootedColor();
					break;
				case OPENING:
					baseColor = config.openingColor();
					break;
				case LOOTABLE:
				default:
					baseColor = config.lootableColor();
					break;
			}
			Color fillColor = withAlpha(baseColor, config.fillOpacity());

			Shape hull = chestState.getGameObject().getConvexHull();
			if (hull != null)
			{
				graphics.setColor(fillColor);
				graphics.fill(hull);
				graphics.setColor(baseColor);
				graphics.draw(hull);
				continue;
			}

			Polygon polygon = chestState.getGameObject().getCanvasTilePoly();
			if (polygon != null)
			{
				graphics.setColor(fillColor);
				graphics.fill(polygon);
				graphics.setColor(baseColor);
				graphics.draw(polygon);
			}
		}

		return null;
	}

	private Color withAlpha(Color color, int alpha)
	{
		return new Color(color.getRed(), color.getGreen(), color.getBlue(), alpha);
	}
}

package com.ketsh11.dorgeshkaanchests;

import com.google.inject.Provides;
import java.awt.Toolkit;
import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Comparator;
import java.util.EnumSet;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Collectors;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.ChatMessageType;
import net.runelite.api.GameObject;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.Scene;
import net.runelite.api.Tile;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.World;
import net.runelite.api.WorldType;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.input.KeyManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.HotkeyListener;
import net.runelite.client.util.Text;

@Slf4j
@PluginDescriptor(
	name = "Dorgesh-Kaan Chests"
)
public class DorgeshKaanChestPlugin extends Plugin
{
	private static final int LOOTABLE_CHEST_ID = 22681;
	private static final int LOOTED_CHEST_ID = 22682;
	private static final int OPENING_CHEST_ID = 22683;
	private static final int ACTIVE_RANGE_TILES = 12;
	private static final long ALL_LOOTED_NOTICE_MILLIS = 3500L;
	private static final String PICK_LOCK_ATTEMPT_MESSAGE = "You attempt to pick the lock.";
	private static final Pattern SKILL_TOTAL_PATTERN = Pattern.compile("(\\d+)\\s*skill\\s*total", Pattern.CASE_INSENSITIVE);
	private static final EnumSet<WorldType> DISALLOWED_WORLD_TYPES = EnumSet.of(
		WorldType.PVP,
		WorldType.HIGH_RISK,
		WorldType.DEADMAN,
		WorldType.BETA_WORLD,
		WorldType.TOURNAMENT_WORLD,
		WorldType.SEASONAL,
		WorldType.PVP_ARENA,
		WorldType.QUEST_SPEEDRUNNING
	);

	@Inject
	private Client client;

	@Inject
	private DorgeshKaanChestConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private KeyManager keyManager;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ConfigManager configManager;

	@Inject
	private DorgeshKaanChestOverlay overlay;

	@Inject
	private DorgeshKaanChestTimerOverlay timerOverlay;

	private final List<ChestState> chestStates = new ArrayList<>();
	private Instant hopReadyAt;
	private Instant allLootedNoticeUntil;
	private Instant lastDefaultWorldHopAt;
	private boolean inChestArea;
	private boolean awaitingPostHopChestCheck;
	private boolean actionRequiredActive;
	private int cycleHopCount;
	private int sessionPicklockAttempts;
	private int sessionHotkeyHops;
	private int sessionAllLootedNotices;

	private final HotkeyListener hopHotkeyListener = new HotkeyListener(() -> config.hopHotkey())
	{
		@Override
		public void hotkeyPressed()
		{
			clientThread.invoke(DorgeshKaanChestPlugin.this::beginHotkeyHopAttempt);
		}
	};

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
		overlayManager.add(timerOverlay);
		keyManager.registerKeyListener(hopHotkeyListener);
		log.debug("Dorgesh-Kaan chests plugin started");
	}

	@Override
	protected void shutDown()
	{
		chestStates.clear();
		hopReadyAt = null;
		allLootedNoticeUntil = null;
		lastDefaultWorldHopAt = null;
		inChestArea = false;
		awaitingPostHopChestCheck = false;
		actionRequiredActive = false;
		cycleHopCount = 0;
		sessionPicklockAttempts = 0;
		sessionHotkeyHops = 0;
		sessionAllLootedNotices = 0;
		keyManager.unregisterKeyListener(hopHotkeyListener);
		overlayManager.remove(overlay);
		overlayManager.remove(timerOverlay);
		log.debug("Dorgesh-Kaan chests plugin stopped");
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.HOPPING)
		{
			awaitingPostHopChestCheck = true;
		}
		else if (event.getGameState() == GameState.LOGGED_IN)
		{
			// Also evaluate chest state after fresh login, not only world hop.
			awaitingPostHopChestCheck = true;
		}

		if (event.getGameState() != GameState.LOGGED_IN)
		{
			hopReadyAt = null;
			allLootedNoticeUntil = null;
			inChestArea = false;
			actionRequiredActive = false;
			// Keep cycle progress across world hops; only reset on true logout to login screen.
			if (event.getGameState() == GameState.LOGIN_SCREEN)
			{
				cycleHopCount = 0;
			}
		}
	}

	@Subscribe
	public void onGameTick(GameTick gameTick)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			chestStates.clear();
			hopReadyAt = null;
			inChestArea = false;
			actionRequiredActive = false;
			return;
		}

		Scene scene = client.getScene();
		Tile[][][] tiles = scene.getTiles();
		Tile[][] planeTiles = tiles[client.getPlane()];
		if (planeTiles == null)
		{
			chestStates.clear();
			return;
		}

		Player localPlayer = client.getLocalPlayer();
		WorldPoint playerLocation = localPlayer != null ? localPlayer.getWorldLocation() : null;
		List<ChestState> found = new ArrayList<>();

		for (Tile[] row : planeTiles)
		{
			if (row == null)
			{
				continue;
			}

			for (Tile tile : row)
			{
				if (tile == null)
				{
					continue;
				}

				for (GameObject object : tile.getGameObjects())
				{
					if (object == null)
					{
						continue;
					}

					int id = object.getId();
					if (id == LOOTABLE_CHEST_ID || id == LOOTED_CHEST_ID || id == OPENING_CHEST_ID)
					{
						ChestRenderState state = id == LOOTABLE_CHEST_ID
							? ChestRenderState.LOOTABLE
							: id == LOOTED_CHEST_ID
								? ChestRenderState.LOOTED
								: ChestRenderState.OPENING;
						found.add(new ChestState(object, state));
					}
				}
			}
		}

		if (playerLocation != null)
		{
			found.sort((a, b) ->
				Integer.compare(
					a.gameObject.getWorldLocation().distanceTo(playerLocation),
					b.gameObject.getWorldLocation().distanceTo(playerLocation)
				)
			);
		}

		chestStates.clear();
		for (ChestState state : found)
		{
			chestStates.add(state);
			if (chestStates.size() == 2)
			{
				break;
			}
		}

		if (playerLocation == null || found.isEmpty())
		{
			inChestArea = false;
			hopReadyAt = null;
			return;
		}

		int nearestChestDistance = found.stream()
			.mapToInt(state -> state.getGameObject().getWorldLocation().distanceTo(playerLocation))
			.min()
			.orElse(Integer.MAX_VALUE);

		inChestArea = nearestChestDistance <= ACTIVE_RANGE_TILES;
		if (!inChestArea)
		{
			hopReadyAt = null;
		}

		if (awaitingPostHopChestCheck && inChestArea && chestStates.size() >= 2)
		{
			boolean lootableChestNearby = chestStates.stream()
				.anyMatch(state -> state.getRenderState() == ChestRenderState.LOOTABLE);

			if (!lootableChestNearby)
			{
				allLootedNoticeUntil = Instant.now().plusMillis(ALL_LOOTED_NOTICE_MILLIS);
				sessionAllLootedNotices++;
			}

			awaitingPostHopChestCheck = false;
		}

		updateAfkSafeAlerts();
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		if (event.getType() != ChatMessageType.SPAM && event.getType() != ChatMessageType.GAMEMESSAGE)
		{
			return;
		}

		String message = Text.removeTags(event.getMessage());
		if (message == null)
		{
			return;
		}

		if (inChestArea && PICK_LOCK_ATTEMPT_MESSAGE.equals(message))
		{
			hopReadyAt = Instant.now().plusMillis(config.hopCountdownMillis());
			sessionPicklockAttempts++;
		}
	}

	@Provides
	DorgeshKaanChestConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(DorgeshKaanChestConfig.class);
	}

	List<ChestState> getChestStates()
	{
		return Collections.unmodifiableList(chestStates);
	}

	DorgeshKaanChestConfig getConfig()
	{
		return config;
	}

	boolean isSwitchLocked()
	{
		return getSecondsUntilHopReady() > 0;
	}

	Integer getSwitchLockSecondsRemaining()
	{
		int seconds = getSecondsUntilHopReady();
		return seconds > 0 ? seconds : 0;
	}

	String getHopIndicatorText()
	{
		if (!inChestArea)
		{
			return null;
		}

		if (allLootedNoticeUntil != null && Instant.now().isBefore(allLootedNoticeUntil))
		{
			return "ALL CHESTS LOOTED";
		}

		boolean lootableChestNearby = chestStates.stream()
			.anyMatch(state -> state.getRenderState() == ChestRenderState.LOOTABLE);
		if (lootableChestNearby)
		{
			return null;
		}

		if (hopReadyAt == null)
		{
			return null;
		}

		int seconds = getSecondsUntilHopReady();
		if (seconds > 0)
		{
			return "HOP IN " + seconds + "s";
		}

		World[] worlds = client.getWorldList();
		if (worlds == null || worlds.length == 0)
		{
			return "OPEN THE WORLD SWITCHER PANEL TO ENABLE AUTO-HOP";
		}

		return "HOP NOW";
	}

	private int getSecondsUntilHopReady()
	{
		if (hopReadyAt == null)
		{
			return 0;
		}
		long millis = Duration.between(Instant.now(), hopReadyAt).toMillis();
		return (int) Math.max(0, (millis + 999) / 1000);
	}

	private void beginHotkeyHopAttempt()
	{
		if (!isHopNowActive())
		{
			return;
		}
		World[] worlds = client.getWorldList();
		if (worlds == null || worlds.length == 0)
		{
			client.addChatMessage(
				ChatMessageType.GAMEMESSAGE,
				"",
				"Open the World Hopper panel once before using hop hotkey.",
				null
			);
			return;
		}

		World target = findNextHopWorld();
		if (target == null)
		{
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "No suitable world found (filters/requirements).", null);
			return;
		}

		client.hopToWorld(target);
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "Hopping to world " + target.getId() + ".", null);
		if (target.getId() == config.defaultWorld())
		{
			lastDefaultWorldHopAt = Instant.now();
			cycleHopCount = 0;
		}
		else if (config.defaultWorld() > 0)
		{
			cycleHopCount = Math.min(Math.max(1, config.hopCycleLength()), cycleHopCount + 1);
		}
		sessionHotkeyHops++;
	}

	private boolean isHopNowActive()
	{
		if (!inChestArea || hopReadyAt == null)
		{
			return false;
		}

		if (getSecondsUntilHopReady() > 0)
		{
			return false;
		}

		boolean lootableChestNearby = chestStates.stream()
			.anyMatch(state -> state.getRenderState() == ChestRenderState.LOOTABLE);
		return !lootableChestNearby;
	}

	private World findNextHopWorld()
	{
		World[] worlds = client.getWorldList();
		if (worlds == null || worlds.length == 0)
		{
			return null;
		}

		boolean onMembersWorld = client.getWorldType().contains(WorldType.MEMBERS);
		List<World> candidates = Arrays.stream(worlds)
			.filter(world -> isWorldAllowed(world, onMembersWorld))
			.sorted(Comparator.comparingInt(World::getId))
			.collect(Collectors.toList());

		if (candidates.isEmpty())
		{
			return null;
		}

		World defaultCycleTarget = findDefaultCycleTarget(candidates);
		if (defaultCycleTarget != null)
		{
			return defaultCycleTarget;
		}

		return findNextFromCurrentWorld(candidates);
	}

	private World findDefaultCycleTarget(List<World> candidates)
	{
		int defaultWorld = config.defaultWorld();
		if (defaultWorld <= 0)
		{
			return null;
		}

		int cycleLength = Math.max(1, config.hopCycleLength());
		if (cycleHopCount < cycleLength)
		{
			return null;
		}

		World target = null;
		for (World candidate : candidates)
		{
			if (candidate.getId() == defaultWorld)
			{
				target = candidate;
				break;
			}
		}

		if (target == null)
		{
			return null;
		}

		// If we're due to revisit default world but respawn isn't ready yet, skip it once.
		if (!isDefaultWorldRespawnReady())
		{
			return null;
		}

		int currentWorldId = client.getWorld();
		if (target.getId() == currentWorldId)
		{
			cycleHopCount = 0;
			return null;
		}

		return target;
	}

	private World findNextFromCurrentWorld(List<World> candidates)
	{
		int currentWorldId = client.getWorld();
		for (World world : candidates)
		{
			if (world.getId() > currentWorldId)
			{
				return world;
			}
		}

		World fallback = candidates.get(0);
		if (fallback.getId() == currentWorldId && candidates.size() > 1)
		{
			return candidates.get(1);
		}

		return fallback;
	}

	private boolean isWorldAllowed(World world, boolean onMembersWorld)
	{
		if (config.hopFilterSource() == HopFilterSource.WORLD_HOPPER)
		{
			return isWorldAllowedByWorldHopper(world);
		}
		return isWorldAllowedInternal(world, onMembersWorld);
	}

	private boolean isWorldAllowedInternal(World world, boolean onMembersWorld)
	{
		if (world == null || world.getId() <= 0)
		{
			return false;
		}

		EnumSet<WorldType> types = world.getTypes();
		if (types == null)
		{
			return false;
		}

		boolean worldIsMembers = types.contains(WorldType.MEMBERS);
		if (worldIsMembers != onMembersWorld)
		{
			return false;
		}

		if (!meetsSkillTotalRequirement(world, types))
		{
			return false;
		}

		for (WorldType disallowed : DISALLOWED_WORLD_TYPES)
		{
			if (types.contains(disallowed))
			{
				return false;
			}
		}

		return true;
	}

	private boolean isWorldAllowedByWorldHopper(World world)
	{
		if (world == null || world.getId() <= 0)
		{
			return false;
		}

		EnumSet<WorldType> types = world.getTypes();
		if (types == null)
		{
			return false;
		}

		if (!meetsSkillTotalRequirement(world, types))
		{
			return false;
		}

		String subscriptionFilter = configManager.getConfiguration("worldhopper", "subscriptionFilter");
		boolean worldIsMembers = types.contains(WorldType.MEMBERS);
		if ("FREE".equals(subscriptionFilter) && worldIsMembers)
		{
			return false;
		}
		if ("MEMBERS".equals(subscriptionFilter) && !worldIsMembers)
		{
			return false;
		}

		Set<String> selectedWorldTypeFilters = parseEnumSet(configManager.getConfiguration("worldhopper", "worldTypeFilter"));
		if (!selectedWorldTypeFilters.isEmpty() && !matchesWorldTypeFilters(selectedWorldTypeFilters, types))
		{
			return false;
		}

		Set<String> selectedRegions = parseEnumSet(configManager.getConfiguration("worldhopper", "regionFilter"));
		if (!selectedRegions.isEmpty() && !matchesRegionFilters(selectedRegions, world.getLocation()))
		{
			return false;
		}

		return true;
	}

	private Set<String> parseEnumSet(String raw)
	{
		if (raw == null || raw.length() < 2 || "[]".equals(raw))
		{
			return Collections.emptySet();
		}

		String trimmed = raw.trim();
		if (!trimmed.startsWith("[") || !trimmed.endsWith("]"))
		{
			return Collections.emptySet();
		}

		String inner = trimmed.substring(1, trimmed.length() - 1).trim();
		if (inner.isEmpty())
		{
			return Collections.emptySet();
		}

		Set<String> values = new HashSet<>();
		for (String token : inner.split(","))
		{
			String value = token.trim();
			if (!value.isEmpty())
			{
				values.add(value);
			}
		}
		return values;
	}

	private boolean matchesWorldTypeFilters(Set<String> selectedFilters, Set<WorldType> types)
	{
		for (String filter : selectedFilters)
		{
			switch (filter)
			{
				case "NORMAL":
					if (isNormalWorld(types))
					{
						return true;
					}
					break;
				case "DEADMAN":
					if (types.contains(WorldType.DEADMAN))
					{
						return true;
					}
					break;
				case "SEASONAL":
					if (types.contains(WorldType.SEASONAL))
					{
						return true;
					}
					break;
				case "QUEST_SPEEDRUNNING":
					if (types.contains(WorldType.QUEST_SPEEDRUNNING))
					{
						return true;
					}
					break;
				case "FRESH_START_WORLD":
					if (types.contains(WorldType.FRESH_START_WORLD))
					{
						return true;
					}
					break;
				case "PVP":
					if (types.contains(WorldType.PVP))
					{
						return true;
					}
					break;
				case "SKILL_TOTAL":
					if (types.contains(WorldType.SKILL_TOTAL))
					{
						return true;
					}
					break;
				case "HIGH_RISK":
					if (types.contains(WorldType.HIGH_RISK))
					{
						return true;
					}
					break;
				case "BOUNTY_HUNTER":
					if (types.contains(WorldType.BOUNTY))
					{
						return true;
					}
					break;
				default:
					break;
			}
		}

		return false;
	}

	private boolean isNormalWorld(Set<WorldType> types)
	{
		return !types.contains(WorldType.DEADMAN)
			&& !types.contains(WorldType.SEASONAL)
			&& !types.contains(WorldType.QUEST_SPEEDRUNNING)
			&& !types.contains(WorldType.FRESH_START_WORLD)
			&& !types.contains(WorldType.PVP)
			&& !types.contains(WorldType.SKILL_TOTAL)
			&& !types.contains(WorldType.HIGH_RISK)
			&& !types.contains(WorldType.BOUNTY);
	}

	private boolean matchesRegionFilters(Set<String> selectedRegions, int location)
	{
		for (String region : selectedRegions)
		{
			switch (region)
			{
				case "UNITED_STATES":
					// US East + US West
					if (location == 0 || location == 9)
					{
						return true;
					}
					break;
				case "UNITED_KINGDOM":
					if (location == 1)
					{
						return true;
					}
					break;
				case "AUSTRALIA":
					if (location == 3)
					{
						return true;
					}
					break;
				case "GERMANY":
					if (location == 7)
					{
						return true;
					}
					break;
				case "BRAZIL":
					if (location == 8)
					{
						return true;
					}
					break;
				default:
					break;
			}
		}

		return false;
	}

	private boolean isDefaultWorldRespawnReady()
	{
		if (lastDefaultWorldHopAt == null)
		{
			return true;
		}

		long elapsedSeconds = Duration.between(lastDefaultWorldHopAt, Instant.now()).getSeconds();
		return elapsedSeconds >= Math.max(1, config.chestRespawnSeconds());
	}

	private boolean meetsSkillTotalRequirement(World world, Set<WorldType> worldTypes)
	{
		if (!worldTypes.contains(WorldType.SKILL_TOTAL))
		{
			return true;
		}

		String activity = world.getActivity();
		if (activity == null)
		{
			return true;
		}

		Matcher matcher = SKILL_TOTAL_PATTERN.matcher(activity);
		if (!matcher.find())
		{
			return true;
		}

		try
		{
			int requiredTotal = Integer.parseInt(matcher.group(1));
			return client.getTotalLevel() >= requiredTotal;
		}
		catch (NumberFormatException ex)
		{
			return true;
		}
	}

	String getStatisticsText()
	{
		if (!config.showStatistics())
		{
			return null;
		}

		return "Attempts: " + sessionPicklockAttempts
			+ " | Hotkey hops: " + sessionHotkeyHops
			+ " | All-looted: " + sessionAllLootedNotices
			+ " | Cycle: " + cycleHopCount + "/" + Math.max(1, config.hopCycleLength());
	}

	boolean isActionRequiredIndicator()
	{
		String text = getHopIndicatorText();
		return "HOP NOW".equals(text) || "ALL CHESTS LOOTED".equals(text);
	}

	private void updateAfkSafeAlerts()
	{
		boolean nowRequired = isActionRequiredIndicator();
		if (config.afkSafeMode() && nowRequired && !actionRequiredActive)
		{
			try
			{
				Toolkit.getDefaultToolkit().beep();
			}
			catch (Exception ignored)
			{
				// Beep is best-effort only.
			}
		}
		actionRequiredActive = nowRequired;
	}

	static class ChestState
	{
		private final GameObject gameObject;
		private final ChestRenderState renderState;

		private ChestState(GameObject gameObject, ChestRenderState renderState)
		{
			this.gameObject = gameObject;
			this.renderState = renderState;
		}

		GameObject getGameObject()
		{
			return gameObject;
		}

		ChestRenderState getRenderState()
		{
			return renderState;
		}
	}

	enum ChestRenderState
	{
		LOOTABLE,
		LOOTED,
		OPENING
	}
}

